// The interaction kinds (opgaveformer) the question bank can hold, and which of them the current
// client can show. ONE registry for the server: the format mix (get-next-question/format-mix.ts) reads
// its limits from here, and a new kind is added here — not by rewriting the mix.
//
// WHY A REGISTRY
// A question's kind is spread over three stored fields (answer_format, answer_type, content.force_text),
// and the server and the browser each derived it on their own:
//   * get-next-question mapAnswerFormat() maps ANY unknown answer_format to "mc", so a future
//     "match" (Match par) row would be handed to the browser as multiple choice;
//   * process-event treats answer_type "long" as teacher-graded whatever answer_format says;
//   * js/answer-input.js resolveAnswerRenderer() decides what the pupil actually sees.
// classifyQuestion() names the kind only where those three agree, and returns null otherwise. A null
// (or a kind marked servable: false) is never served as a NEW question by the mix engine.
//
// THE KINDS (renderer = js/answer-input.js ANSWER_RENDERERS value the browser uses for it)
//   choice       answer_format "mc…"                     auto-graded   renderer "choice"
//   short_text   answer_format "text", answer_type short  auto-graded   renderer "short_text" (Stav til)
//   long_text    answer_format "text", answer_type long   TEACHER-graded renderer "long_text"
//                maxShare 0: process-event keeps a long answer OPEN (answered = false) until the teacher
//                grades it, and idx_one_open_question allows one open instance per pupil — so a long
//                question chosen by quota would hold the pupil on that one question until the teacher
//                acts. Long answers are served when the pool holds nothing else, never to fill a share.
//   number       answer_format "…number…"                auto-graded   renderer "number"
//   force_text   content.force_text === true (non-long)   auto-graded   renderer "force_text"
//   match_pairs  answer_format "match" (ROADMAP #13)      auto-graded   renderer "match_pairs" — BUILT, NOT
//                servable: contract, key and answer shape in _shared/match-pairs.ts; graded by
//                process_question_attempt like MC (process-event canonicalises the connections first)
//   true_false   answer_format "true_false" (F-02)        auto-graded   renderer "true_false" — BUILT, NOT
//                servable: contract and key in _shared/true-false.ts; the key is the option text
//                ("Sandt"/"Falsk"), so process_question_attempt grades it with normalize_choice_answer
//                exactly like MC — no grading change in process-event or SQL. Its own wire format
//                (not "mc"): the browser pads answer_format "mc" to four options with legacy years
//                (js/answer-options.js), which a two-choice task must never get. maxShare 0 until the
//                owner decides its share (it is a forståelsestjek, docs/learning-progression-design.md).
//   order_items  answer_format "order" (ROADMAP #12)      auto-graded   renderer "order_items" — SERVABLE
//                (F-04, step 3 below, D-362): contract, key and answer shape in _shared/order-items.ts (the
//                facit is the authored order; only the presentation is shuffled); graded by
//                process_question_attempt like Match par (process-event checks the answer's shape first —
//                only the repository's process-event does; production needs step Q-21 first, see
//                migration 20261108090000)
//   categorize   answer_format "categorize" (F-05)       auto-graded   renderer "categorize" — SERVABLE
//                (F-05, step 3 below, D-362): contract, key and answer shape in _shared/categorize.ts (each
//                item's category is authored; only the presentation of the items is shuffled); graded by
//                process_question_attempt like Match par and Rækkefølge (process-event checks the shape
//                first — only the repository's process-event does; production needs step Q-21 first, see
//                migration 20261108090000)
//
// GUESS FLOOR (guessFloor)
// The chance that a pure random answer is right, where that is a FIXED property of the kind. Future
// mastery logic must never count one correct answer of a kind with a high floor as mastery
// (docs/learning-progression-design.md, the guess-floor table). null = not a fixed property of the kind:
// choice is 1/(number of options) and match_pairs 1/(n! − 1) per question, and typed answers are ≈ 0 —
// none of them is modelled yet, so a reader must treat null as "unknown", never as 0. Nothing on the
// serving or grading path reads this field today.
//
// ADDING A KIND (Match par and Sandt/falsk have done steps 1 and 2; Rækkefølge and Kategorisering all
// three, D-362) — the order matters, each step is its own reviewed change:
//   1. add the entry below with servable: false (content may then be authored, inactive or not,
//      and is never served);
//   2. ship the renderer (js/answer-input.js) and the grading path (process-event /
//      process_question_attempt) and extend the public DTO (_shared/question-dto.ts) on purpose;
//   3. flip servable to true in the same PR that ships the renderer, with the parity test in
//      tests/unit/interaction-kinds.test.mjs extended to the new renderer.
// The SQL twin public.question_is_servable (migration 20261019150000) must change in the same PR as
// step 3: it decides what the candidate window and the repeat exhaustion check count as servable, and
// tests/unit/question-format-mix-migration-run.test.mjs fails while the two disagree. The candidate
// window itself needs no change: it stratifies by the stored fields, not by kind names.
// Match par, step 3 also: get-next-question's v1 mapAnswerFormat still maps "match" to "mc" (the row is
// then skipped, because it has no options), so Match par reaches pupils only under QUESTION_MIX_ENGINE=v2
// until v1 is retired or taught "match" in the same reviewed change. The same holds for "true_false".
// Both also need a reviewed migration before a row can even be STORED: production's questions table
// checks answer_format (questions_answer_format_check: mc, number, text) and content
// (content_valid_check: content.type mc/text/number), and neither admits "match" or "true_false".
// Rækkefølge and Kategorisering, step 3 (D-362): v1's mapAnswerFormat maps "order" and "categorize" to
// themselves (exact match), and migration 20261108090000 (NOT applied) lets the questions table store
// both and flips question_is_servable for them.
//
// Pure TypeScript with no Deno or network imports, so the Node unit suite tests exactly what the
// Edge Functions run.

export type InteractionKind =
  | "choice"
  | "short_text"
  | "long_text"
  | "number"
  | "force_text"
  | "match_pairs"
  | "true_false"
  | "order_items"
  | "categorize";

export type InteractionKindSpec = {
  // The answer_format value get-next-question sends to the browser for this kind.
  wireFormat: "mc" | "text" | "number" | "match" | "true_false" | "order" | "categorize";
  // js/answer-input.js ANSWER_RENDERERS value, or null when no client renderer exists yet.
  renderer: string | null;
  // May the server hand this kind out as a NEW question to the current client?
  servable: boolean;
  // The base kind fills every slot the mix does not give to another kind. Exactly one kind is base.
  base: boolean;
  // Upper share of NEW questions in the mix window (non-base kinds only; 0 for the base kind).
  // 0 for a non-base kind = never chosen BY QUOTA; it is still served when nothing else is left.
  maxShare: number;
  // Teacher-graded work creates teacher load and waits for a verdict; never repeated automatically.
  teacherGraded: boolean;
  // Chance that a pure random answer is right, when that is fixed for the kind; null = depends on the
  // question or is not modelled (see GUESS FLOOR above). Read by nothing on the serving path.
  guessFloor: number | null;
};

export const INTERACTION_KINDS: Readonly<Record<InteractionKind, Readonly<InteractionKindSpec>>> = Object.freeze({
  choice:      Object.freeze({ wireFormat: "mc",          renderer: "choice",     servable: true,  base: true,  maxShare: 0,    teacherGraded: false, guessFloor: null }),
  short_text:  Object.freeze({ wireFormat: "text",        renderer: "short_text", servable: true,  base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
  long_text:   Object.freeze({ wireFormat: "text",        renderer: "long_text",  servable: true,  base: false, maxShare: 0,    teacherGraded: true,  guessFloor: null }),
  number:      Object.freeze({ wireFormat: "number",      renderer: "number",     servable: true,  base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
  force_text:  Object.freeze({ wireFormat: "mc",          renderer: "force_text", servable: true,  base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
  match_pairs: Object.freeze({ wireFormat: "match",       renderer: "match_pairs", servable: false, base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
  true_false:  Object.freeze({ wireFormat: "true_false",  renderer: "true_false", servable: false, base: false, maxShare: 0,    teacherGraded: false, guessFloor: 0.5 }),
  order_items: Object.freeze({ wireFormat: "order",       renderer: "order_items", servable: true,  base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
  categorize:  Object.freeze({ wireFormat: "categorize",  renderer: "categorize",  servable: true,  base: false, maxShare: 0.15, teacherGraded: false, guessFloor: null }),
});

// Registry order is the deterministic tie-break wherever two kinds score the same.
export const KIND_ORDER: readonly InteractionKind[] = Object.freeze(
  Object.keys(INTERACTION_KINDS) as InteractionKind[],
);

export const BASE_KIND: InteractionKind = (() => {
  const base = KIND_ORDER.filter((k) => INTERACTION_KINDS[k].base);
  if (base.length !== 1) throw new Error("interaction-kinds: exactly one base kind is required");
  return base[0];
})();

export type StoredFormatFields = {
  answer_format?: unknown;
  answer_type?: unknown;
  content?: unknown;
  // Already-extracted content.force_text, for reads that select only that key.
  force_text?: unknown;
};

function lower(value: unknown): string {
  return typeof value === "string" ? value.trim().toLowerCase() : "";
}

// The kind of one stored question, or null when the stored fields do not name a kind every layer
// agrees on. Never throws.
export function classifyQuestion(row: StoredFormatFields | null | undefined): InteractionKind | null {
  if (!row || typeof row !== "object") return null;

  // The server's mapAnswerFormat is case- and space-sensitive, the browser lower-cases: only a
  // canonical (lower-case, trimmed) stored format means the same thing to both.
  if (typeof row.answer_format !== "string" || row.answer_format !== lower(row.answer_format)) return null;
  const format = row.answer_format;
  // process-event compares answer_type === "long" exactly, the browser trims and lower-cases; a
  // non-canonical value ("Long") would be graded short and shown long. Null/empty is short to both.
  if (row.answer_type !== null && row.answer_type !== undefined
    && (typeof row.answer_type !== "string" || row.answer_type !== lower(row.answer_type))) return null;
  const answerType = (row.answer_type as string | null | undefined) || "short";
  const content = row.content && typeof row.content === "object" && !Array.isArray(row.content)
    ? row.content as Record<string, unknown>
    : null;
  const forceText = row.force_text === true || content?.force_text === true;

  if (format === "") return null;

  if (answerType === "long") {
    // Teacher-graded on the server. Only "text" also renders as a long answer in the browser; any
    // other stored format would be shown one way and graded another.
    return format === "text" && !forceText ? "long_text" : null;
  }
  if (answerType !== "short") return null;

  if (format === "match") return forceText ? null : "match_pairs";
  if (format === "true_false") return forceText ? null : "true_false";
  if (format === "order") return forceText ? null : "order_items";
  if (format === "categorize") return forceText ? null : "categorize";

  // mapAnswerFormat (server) tests "mc" first, resolveAnswerRenderer (browser) tests "number" first:
  // a format containing both would be graded as one kind and shown as the other.
  if (format.startsWith("mc") && format.includes("number")) return null;

  if (forceText) {
    // The browser's force_text renderer wins over the format; the server grades by format. Only an
    // MC row is graded as free text against its key today.
    return format.startsWith("mc") ? "force_text" : null;
  }

  if (format.startsWith("mc")) return "choice";
  if (format.includes("number")) return "number";
  if (format === "text") return "short_text";
  return null;
}

export function isServableKind(kind: InteractionKind | null): kind is InteractionKind {
  return kind !== null && INTERACTION_KINDS[kind].servable === true;
}

// The answer_format the browser receives for a stored row — or null when the row must not be served.
// Unlike get-next-question's mapAnswerFormat, an unknown format never falls back to "mc".
export function servableWireFormat(row: StoredFormatFields | null | undefined): string | null {
  const kind = classifyQuestion(row);
  return isServableKind(kind) ? INTERACTION_KINDS[kind].wireFormat : null;
}

files.functions/_shared/introduction.ts:
// Lærligverse LP-13 / K9 PROTOTYPE: the introduction as a server step without an answer key (migration
// 20261110043500, docs/laerligverse/eksponering-datakontrakt.md). Pure TypeScript with no Deno or network imports:
// get-next-question and the introduction-progress function use it, the Node unit suite tests it.
//
// SWITCHES (Edge secrets, exactly "on" = on, unset everywhere):
//   LAERLIGVERSE_INTRODUCTION — get-next-question serves an objective's introduction before the first sequence step
//                               (only in a server-directed sequence), and introduction-progress accepts "completed";
//   LAERLIGVERSE_PRESENTED    — introduction-progress also accepts the optional "presented" signal.
//
// The public payload is built field by field from the server's content: only cards[{title, text}] — never a key,
// option, hint or review text (the database also refuses such keys in an introduction).

export const INTRODUCTION_ENV = "LAERLIGVERSE_INTRODUCTION";
export const PRESENTED_ENV = "LAERLIGVERSE_PRESENTED";

export const on = (value: string | undefined | null): boolean => value === "on";

// F12-B: the request's introduction capability (body.introduction_capability). A COMPATIBILITY signal, never an
// authorisation: it can only tell the server that this host and game session can SHOW a server introduction. It never
// grants a task, a reward, evidence or an exemption — without it, a required introduction is not skipped but answered
// with step "introduction_required" and nothing is written.
//   absent    — the field is missing (every client before F12-B, and every host that does not show introductions);
//   supported — exactly the integer 1 (version 1: the cards of step "introduction" + introduction-progress shown/done);
//   invalid   — anything else (another number, a string, true, null …): the request is refused (400), nothing is read
//               or written. A future version is a new integer the server must learn first; it is refused until then.
export const INTRODUCTION_CAPABILITY_FIELD = "introduction_capability";
export const INTRODUCTION_CAPABILITY_VERSION = 1;
export type IntroductionCapability = "absent" | "supported" | "invalid";

export function introductionCapabilityOf(body: unknown): IntroductionCapability {
  if (typeof body !== "object" || body === null || Array.isArray(body)) return "absent";
  if (!Object.prototype.hasOwnProperty.call(body, INTRODUCTION_CAPABILITY_FIELD)) return "absent";
  const v = (body as Record<string, unknown>)[INTRODUCTION_CAPABILITY_FIELD];
  return v === INTRODUCTION_CAPABILITY_VERSION ? "supported" : "invalid";
}

/**
 * F12-B: is an introduction REQUIRED for this pupil and objective, decided WITHOUT writing (for a request that cannot
 * show it)? The same rule as serve_introduction (migration 20261110043500): a round of ANY version of the objective's
 * introduction decides — completed → not required, not completed → required; without a round, an ACTIVE introduction
 * for the objective → required; none → not required. The rows are read on the backend client (service_role has SELECT
 * on both tables); `round` is the pupil's earliest round of the objective (or null), `activeIntroduction` whether one
 * is active. Anything malformed is a contract break (error), never "not required".
 */
export type RequiredDecision = { kind: "required" } | { kind: "not_required" } | { kind: "error"; problem: string };

export function introductionRequired(rounds: unknown, active: unknown): RequiredDecision {
  if (!Array.isArray(rounds) || !Array.isArray(active)) return { kind: "error", problem: "rows are not arrays" };
  if (rounds.length > 0) {
    const r = rounds[0];
    if (typeof r !== "object" || r === null || !Object.prototype.hasOwnProperty.call(r, "completed_at")) {
      return { kind: "error", problem: "round without completed_at" };
    }
    const completedAt = (r as Record<string, unknown>).completed_at;
    if (completedAt !== null && typeof completedAt !== "string") return { kind: "error", problem: "invalid completed_at" };
    return completedAt === null ? { kind: "required" } : { kind: "not_required" };
  }
  return active.length > 0 ? { kind: "required" } : { kind: "not_required" };
}

const MAX_CARDS = 10;
const MAX_TITLE = 200;
const MAX_TEXT = 2000;

export type IntroCard = { title: string; text: string };

/** The public cards of an introduction's content, or null when the content is not a valid introduction. */
export function publicIntroduction(content: unknown): { cards: IntroCard[] } | null {
  if (typeof content !== "object" || content === null || Array.isArray(content)) return null;
  const cards = (content as Record<string, unknown>).cards;
  if (!Array.isArray(cards) || cards.length < 1 || cards.length > MAX_CARDS) return null;
  const out: IntroCard[] = [];
  for (const c of cards) {
    if (typeof c !== "object" || c === null) return null;
    const { title, text } = c as Record<string, unknown>;
    if (typeof title !== "string" || typeof text !== "string" || title.trim() === "" || text.trim() === ""
      || title.length > MAX_TITLE || text.length > MAX_TEXT) return null;
    out.push({ title, text });
  }
  return { cards: out };
}

export type ServeDecision =
  | { kind: "show"; roundId: string; contentSha256: string; cards: IntroCard[] }
  | { kind: "continue" }
  | { kind: "error"; problem: string };

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** serve_introduction's jsonb → show the introduction, continue with the sequence, or a contract break. */
export function decideIntroduction(data: unknown): ServeDecision {
  if (typeof data !== "object" || data === null || Array.isArray(data)) return { kind: "error", problem: "result is not an object" };
  const r = data as Record<string, unknown>;
  if (r.outcome === "none" || r.outcome === "completed") return { kind: "continue" };
  if (r.outcome === "served" || r.outcome === "resumed") {
    if (typeof r.round_id !== "string" || !UUID.test(r.round_id)) return { kind: "error", problem: "invalid round_id" };
    if (typeof r.content_sha256 !== "string" || !/^[0-9a-f]{64}$/.test(r.content_sha256)) return { kind: "error", problem: "invalid content_sha256" };
    const pub = publicIntroduction(r.content);
    if (pub === null) return { kind: "error", problem: "invalid introduction content" };
    return { kind: "show", roundId: r.round_id, contentSha256: r.content_sha256, cards: pub.cards };
  }
  return { kind: "error", problem: "unknown outcome" };
}

files.functions/_shared/learning-sequence.ts:
// Server-directed learning sequence for ONE learning objective (Lærligverse F6, D-338). Pure TypeScript with
// no Deno or network imports: get-next-question runs it, the Node unit suite tests it, and the local
// demo's test adapter runs the very same file (generated JS), so the demo cannot drift from the server.
//
// WHAT IT DECIDES. Given the pupil's own SERVER history in the objective (question_instances joined with the
// question's step tag), which learning step comes next — or that the pupil must wait (revisit), or that the
// sequence is complete. The client never decides the step: a client that asks for another step is refused.
//
// WHAT IT DOES NOT DECIDE. Mastery, level, evidence, reward. A step being "complete" means only "an answer
// for that step has been recorded"; it says nothing about learning (D-330: a correct answer is not
// documented learning). There is no skipping rule: every step is served, except revision, which the policy
// inserts only after an incorrect guided-practice answer.
//
// STATUS. The transitions below are an explicit, PROVISIONAL TEST POLICY ("laerligverse-test-policy-v0").
// The real rules are an owner decision (LP-13). The step ids are this prototype's; the activity modes are
// D-277's enum (quiz_v1 | diagnostic | practice | check | review | application), the vocabulary L1 K1 (#536)
// records in question_attempts.mode.
//
// Introduction and exploration are NOT server steps: the server records no exposure today (LPD §5.3), so it
// cannot know them, and it must not pretend to.

export const POLICY_ID = "laerligverse-test-policy-v0";

export type StepId = "guided_practice" | "revision" | "independent_application" | "transfer" | "revisit";
export type Mode = "practice" | "check" | "review" | "application";

export interface StepDef {
  readonly id: StepId;
  /** D-277 activity mode the server declares for an item of this step. */
  readonly mode: Mode;
  /** Teaching / practice / assessment — what the step is FOR. */
  readonly kind: "practice" | "assessment";
  /** May an answer in this step ever become learning evidence (subject to K4/K5 and registered help)? */
  readonly mayBecomeEvidence: boolean;
}

export const STEPS: readonly StepDef[] = Object.freeze([
  { id: "guided_practice", mode: "practice", kind: "practice", mayBecomeEvidence: false },
  { id: "revision", mode: "practice", kind: "practice", mayBecomeEvidence: false },
  { id: "independent_application", mode: "check", kind: "assessment", mayBecomeEvidence: true },
  { id: "transfer", mode: "application", kind: "assessment", mayBecomeEvidence: true },
  { id: "revisit", mode: "review", kind: "assessment", mayBecomeEvidence: true },
] as const);

export const STEP_IDS: readonly StepId[] = Object.freeze(STEPS.map((s) => s.id));

/** PROPOSAL (LPD §4.3, a heuristic): the revisit is due this long after the transfer was answered. */
export const REVISIT_AFTER_HOURS = 20;

export function stepDef(id: StepId): StepDef {
  return STEPS.find((s) => s.id === id) as StepDef;
}

/** The step tag of a question (questions.metadata.learning_step), or null when untagged/unknown. */
export function stepOf(metadata: unknown): StepId | null {
  if (typeof metadata !== "object" || metadata === null) return null;
  const v = (metadata as Record<string, unknown>).learning_step;
  return typeof v === "string" && (STEP_IDS as readonly string[]).includes(v) ? (v as StepId) : null;
}

/** One SERVER fact: an instance the pupil was served in this objective. */
export interface HistoryEntry {
  readonly step: StepId | null;
  readonly answered: boolean;
  readonly wasCorrect: boolean | null;
  readonly answeredAt: string | null;
}

export type SequenceDecision =
  | { readonly state: "step"; readonly step: StepId; readonly mode: Mode; readonly policy: string }
  | { readonly state: "waiting"; readonly step: "revisit"; readonly dueAt: string; readonly policy: string }
  | { readonly state: "complete"; readonly policy: string };

const answeredIn = (h: readonly HistoryEntry[], step: StepId) =>
  h.filter((e) => e.step === step && e.answered).sort((a, b) => Date.parse(a.answeredAt ?? "") - Date.parse(b.answeredAt ?? ""));

const at = (step: StepId): SequenceDecision => ({ state: "step", step, mode: stepDef(step).mode, policy: POLICY_ID });

/**
 * The next step for the pupil, from the server's own history only. Deterministic; unanswered instances
 * do not move the sequence (an open round is resumed in its own step by the caller).
 */
export function nextStep(history: readonly HistoryEntry[], nowMs: number): SequenceDecision {
  const practice = answeredIn(history, "guided_practice");
  if (practice.length === 0) return at("guided_practice");
  // Revision is inserted only when the LATEST guided-practice answer was incorrect (test policy v0).
  const latestPractice = practice[practice.length - 1] as HistoryEntry;
  if (latestPractice.wasCorrect === false && answeredIn(history, "revision").length === 0) return at("revision");
  if (answeredIn(history, "independent_application").length === 0) return at("independent_application");
  const transfer = answeredIn(history, "transfer");
  if (transfer.length === 0) return at("transfer");
  if (answeredIn(history, "revisit").length > 0) return { state: "complete", policy: POLICY_ID };
  const due = Date.parse((transfer[0] as HistoryEntry).answeredAt ?? "") + REVISIT_AFTER_HOURS * 3_600_000;
  if (!Number.isFinite(due)) return { state: "waiting", step: "revisit", dueAt: "unknown", policy: POLICY_ID };
  return nowMs >= due ? at("revisit") : { state: "waiting", step: "revisit", dueAt: new Date(due).toISOString(), policy: POLICY_ID };
}

/**
 * A client may NAME the step it expects (to detect a stale view), never CHOOSE one. Anything but the
 * server's current step is refused.
 */
export function checkRequestedStep(requested: unknown, decision: SequenceDecision):
  | { ok: true }
  | { ok: false; status: 400 | 409; error: "invalid_learning_step" | "learning_step_not_current" } {
  if (requested === undefined || requested === null) return { ok: true };
  if (typeof requested !== "string" || !(STEP_IDS as readonly string[]).includes(requested)) return { ok: false, status: 400, error: "invalid_learning_step" };
  if (decision.state !== "step" || decision.step !== requested) return { ok: false, status: 409, error: "learning_step_not_current" };
  return { ok: true };
}

/** question_instances rows (answered, was_correct, answered_at, questions{metadata}) → history. */
export function historyFromRows(rows: unknown): HistoryEntry[] {
  if (!Array.isArray(rows)) return [];
  return rows.map((r) => {
    const row = (typeof r === "object" && r !== null ? r : {}) as Record<string, unknown>;
    const q = (typeof row.questions === "object" && row.questions !== null ? row.questions : {}) as Record<string, unknown>;
    return {
      step: stepOf(q.metadata),
      answered: row.answered === true,
      wasCorrect: typeof row.was_correct === "boolean" ? row.was_correct : null,
      answeredAt: typeof row.answered_at === "string" ? row.answered_at : null,
    };
  });
}

files.functions/_shared/match-pairs.ts:
// Match par (match_pairs): the pupil connects each item in a left column with the item in a right
// column that belongs to it. This file is the SERVER contract for the kind — stored content, the
// per-instance answer key, the browser layout and the shape of an answer. It decides nothing about
// rewards and does not grade: correctness is decided by public.process_question_attempt, exactly as
// for multiple choice and numbers (see "GRADING" below), so Match par has no grading path of its own.
//
// STORED CONTENT (questions row: answer_format "match", answer_type "short")
//   content.question   string, the task ("Forbind landet med hovedstaden")
//   content.pairs      MATCH_MIN_PAIRS..MATCH_MAX_PAIRS objects { left: string, right: string } in the
//                      authored order; every left text is unique and every right text is unique, so
//                      no answer can be right in two ways
//   content.options    must be ABSENT: get-next-question's v1 path maps an unknown format to "mc", and
//                      a match row without options then fails the MC payload check and is skipped —
//                      it is never shown as multiple choice
// Nothing else in content is read. difficulty_band / target_grade differentiate as for any question;
// RECOMMENDED_PAIRS_BY_BAND is the authoring guidance for how many pairs a band should hold.
//
// THE ANSWER KEY (question_instances.correct_answer, server-only)
// The left column is shown in authored order; the right column is shuffled ONCE, when the instance is
// created, and the shuffle is stored as the instance's key:
//   "0:2,1:0,2:1"  = left item 0 belongs with right DISPLAY position 2, left 1 with right 0, …
// The key alone rebuilds the browser layout (right display position j shows pairs[i].right where
// key[i] = j), so a due or repeated instance looks exactly as it did when it was first served, and the
// browser never receives anything that names which right item belongs to which left item — only two
// lists of texts. The shuffle is never the identity, so "straight across" is never the answer.
//
// GRADING
// The browser sends its connections as JSON, [[left, right], …] in display positions.
// canonicalMatchAnswer() checks only the SHAPE — exactly one connection per left item and per right
// item — and writes it in the key's canonical form, sorted by left. process-event then hands that string
// to process_question_attempt, which compares it with the key (both lower-cased and stripped to
// [a-z0-9], so "0:2,1:0,2:1" and the key compare as "021021"; with at most 6 pairs every position is one
// digit, so the stripped form is unambiguous) and awards XP, coins, streak, quests and the reduced
// repeat award exactly as it does for MC. An incomplete or malformed answer is rejected before the RPC:
// nothing is recorded and nothing is awarded.
//
// Pure TypeScript with no Deno or network imports, so the Node unit suite tests exactly what the Edge
// Functions run.

export const MATCH_MIN_PAIRS = 2;
export const MATCH_MAX_PAIRS = 6;
export const MATCH_MAX_TEXT_LENGTH = 80;

// Authoring guidance per difficulty band (1–5): more pairs are harder to hold in mind at once. A band
// outside this table, or a count outside its range, is a content warning, not a serving error.
export const RECOMMENDED_PAIRS_BY_BAND: Readonly<Record<number, readonly [number, number]>> = Object.freeze({
  1: Object.freeze([2, 3]) as readonly [number, number],
  2: Object.freeze([3, 4]) as readonly [number, number],
  3: Object.freeze([4, 4]) as readonly [number, number],
  4: Object.freeze([4, 5]) as readonly [number, number],
  5: Object.freeze([5, 6]) as readonly [number, number],
});

export type MatchPair = { left: string; right: string };
export type MatchLayout = { left: string[]; right: string[] };

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isItemText(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0 && value.length <= MATCH_MAX_TEXT_LENGTH;
}

// The authored pairs, or a thrown Error naming what is wrong. Used both when an instance is created and
// when its layout is rebuilt, so a row that breaks the contract is skipped rather than served half-built.
export function parseMatchPairs(rawContent: unknown): MatchPair[] {
  if (!isPlainObject(rawContent)) throw new Error("Invalid content");
  if (rawContent.options !== undefined) throw new Error("Match question must not carry options");
  const pairs = rawContent.pairs;
  if (!Array.isArray(pairs) || pairs.length < MATCH_MIN_PAIRS || pairs.length > MATCH_MAX_PAIRS) {
    throw new Error(`Match question needs ${MATCH_MIN_PAIRS}-${MATCH_MAX_PAIRS} pairs`);
  }
  const out: MatchPair[] = [];
  for (const p of pairs) {
    if (!isPlainObject(p) || !isItemText(p.left) || !isItemText(p.right)) {
      throw new Error("Match pair needs a non-empty left and right text");
    }
    out.push({ left: p.left, right: p.right });
  }
  // Compared case- and space-insensitively: two items a pupil cannot tell apart are the same item.
  const norm = (s: string) => s.trim().toLowerCase();
  if (new Set(out.map((p) => norm(p.left))).size !== out.length) throw new Error("Match question has duplicate left items");
  if (new Set(out.map((p) => norm(p.right))).size !== out.length) throw new Error("Match question has duplicate right items");
  return out;
}

// Authoring check: contract errors (the row would be skipped) and warnings (it would be served, but
// does not follow the guidance). Never throws.
export function validateMatchContent(rawContent: unknown, difficultyBand: unknown): { errors: string[]; warnings: string[] } {
  const errors: string[] = [];
  const warnings: string[] = [];
  let pairs: MatchPair[] = [];
  try {
    pairs = parseMatchPairs(rawContent);
  } catch (e) {
    errors.push((e as Error).message);
  }
  if (!isPlainObject(rawContent) || typeof rawContent.question !== "string" || rawContent.question.trim().length === 0) {
    errors.push("Missing question text");
  }
  if (errors.length === 0) {
    const range = Number.isInteger(difficultyBand) ? RECOMMENDED_PAIRS_BY_BAND[difficultyBand as number] : undefined;
    if (!range) warnings.push("difficulty_band 1-5 is required to check the pair count");
    else if (pairs.length < range[0] || pairs.length > range[1]) {
      warnings.push(`band ${difficultyBand} recommends ${range[0]}-${range[1]} pairs, this question has ${pairs.length}`);
    }
  }
  return { errors, warnings };
}

// A uniform integer in [0, maxExclusive) from the platform's cryptographic generator (Deno and Node
// both provide globalThis.crypto). Injected in tests.
export type RandomInt = (maxExclusive: number) => number;

export const cryptoRandomInt: RandomInt = (maxExclusive) => {
  if (!Number.isInteger(maxExclusive) || maxExclusive < 1 || maxExclusive > 256) {
    throw new Error("cryptoRandomInt: range must be 1..256");
  }
  // Rejection sampling: no modulo bias.
  const limit = 256 - (256 % maxExclusive);
  const buf = new Uint8Array(1);
  for (;;) {
    globalThis.crypto.getRandomValues(buf);
    if (buf[0] < limit) return buf[0] % maxExclusive;
  }
};

function formatKey(rightPositionOfLeft: readonly number[]): string {
  return rightPositionOfLeft.map((r, l) => `${l}:${r}`).join(",");
}

// A fresh key for an instance of a question with `pairCount` pairs: a Fisher–Yates shuffle of the
// right column that is never the identity.
export function createMatchKey(pairCount: number, randomInt: RandomInt = cryptoRandomInt): string {
  if (!Number.isInteger(pairCount) || pairCount < MATCH_MIN_PAIRS || pairCount > MATCH_MAX_PAIRS) {
    throw new Error("createMatchKey: invalid pair count");
  }
  // order[j] = the authored pair shown at right display position j.
  const order = Array.from({ length: pairCount }, (_, i) => i);
  for (let i = pairCount - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    if (!Number.isInteger(j) || j < 0 || j > i) throw new Error("createMatchKey: random source out of range");
    [order[i], order[j]] = [order[j], order[i]];
  }
  // Identity would line every pair up straight across; rotate by one instead (still a valid shuffle,
  // and deterministic, so no second draw is needed).
  if (order.every((v, i) => v === i)) order.push(order.shift() as number);
  const rightPositionOfLeft = new Array<number>(pairCount);
  order.forEach((pairIndex, position) => { rightPositionOfLeft[pairIndex] = position; });
  return formatKey(rightPositionOfLeft);
}

// The key as an array (index = left position, value = right display position), or null when it is not
// a complete key for `pairCount` pairs (pairCount omitted: any valid size).
export function parseMatchKey(key: unknown, pairCount?: number): number[] | null {
  if (typeof key !== "string") return null;
  const parts = key.split(",");
  if (parts.length < MATCH_MIN_PAIRS || parts.length > MATCH_MAX_PAIRS) return null;
  if (pairCount !== undefined && parts.length !== pairCount) return null;
  const out: number[] = [];
  for (let i = 0; i < parts.length; i++) {
    const m = /^(\d):(\d)$/.exec(parts[i]);
    if (!m || Number(m[1]) !== i) return null;
    out.push(Number(m[2]));
  }
  const sorted = [...out].sort((a, b) => a - b);
  return sorted.every((v, i) => v === i) ? out : null;
}

// What the browser may see: the left texts in authored order and the right texts in the instance's
// shuffled order. Throws when the content or the key is unusable, so the caller skips the row.
export function matchLayout(rawContent: unknown, key: unknown): MatchLayout {
  const pairs = parseMatchPairs(rawContent);
  const positions = parseMatchKey(key, pairs.length);
  if (positions === null) throw new Error("Match question has no valid instance key");
  const right = new Array<string>(pairs.length);
  positions.forEach((position, pairIndex) => { right[position] = pairs[pairIndex].right; });
  return { left: pairs.map((p) => p.left), right };
}

// The pupil's connections in the key's canonical form, or null when they are not exactly one
// connection per left and per right item for a question of the key's size. Accepts the JSON string the
// browser sends, or the already-parsed array. Shape only — never a verdict.
export function canonicalMatchAnswer(answer: unknown, key: unknown): string | null {
  const positions = parseMatchKey(key);
  if (positions === null) return null;
  const n = positions.length;
  let parsed: unknown = answer;
  if (typeof answer === "string") {
    if (answer.length > 200) return null;
    try { parsed = JSON.parse(answer); } catch { return null; }
  }
  if (!Array.isArray(parsed) || parsed.length !== n) return null;
  const rightOfLeft = new Array<number>(n).fill(-1);
  const usedRight = new Set<number>();
  for (const c of parsed) {
    if (!Array.isArray(c) || c.length !== 2) return null;
    const [l, r] = c;
    if (!Number.isInteger(l) || !Number.isInteger(r) || l < 0 || l >= n || r < 0 || r >= n) return null;
    if (rightOfLeft[l] !== -1 || usedRight.has(r)) return null;
    rightOfLeft[l] = r;
    usedRight.add(r);
  }
  return formatKey(rightOfLeft);
}

