// Anti-gætte-pausen (migration 20261105130000_quiz_anti_guess_cooldown.sql, docs/quiz-anti-guess-cooldown.md)
// i process-event: hvordan databasens afvisning bliver et kontrolleret HTTP-svar.
//
// HÅNDHÆVELSEN LIGGER I DATABASEN, IKKE HER
// Triggeren quiz_cooldown_guard på question_instances afviser et bedømt svar under en aktiv pause med
// SQLSTATE LQ429, beskeden 'quiz_cooldown_active' og pausens slut (UTC, ISO 8601) i DETAIL. Fejlen opstår
// inde i svarfunktionens transaktion (process_question_attempt, process_text_answer eller deres _v2),
// så intet er gemt eller betalt, når process-event ser den. Dette modul genkender kun fejlen og former
// svaret; det beslutter intet. En klient, der kalder backend direkte, rammer den samme trigger.
//
// SVARET (stabilt, maskinlæsbart):
//   429 { outcome: "quiz_cooldown", error: "Quiz cooldown", cooldown_until: <ISO|null>, server_now: <ISO> }
// Hverken tærskel, vindue eller antal fejl indgår — eleven må ikke kunne se mekanikken.
//
// Ren TypeScript uden Deno- eller netværksimport, så Node-testene importerer præcis det, funktionen kører
// (samme ordning som ./answer-v2.ts).

export const QUIZ_COOLDOWN_SQLSTATE = "LQ429";
export const QUIZ_COOLDOWN_MESSAGE = "quiz_cooldown_active";

export function isQuizCooldownError(error: unknown): boolean {
  if (!error || typeof error !== "object") return false;
  const { code, message } = error as { code?: unknown; message?: unknown };
  return code === QUIZ_COOLDOWN_SQLSTATE || message === QUIZ_COOLDOWN_MESSAGE;
}

// The end of the pause from the database's DETAIL (PostgREST passes it on as `details`). Anything that is
// not a valid timestamp becomes null: the browser then asks get_my_quiz_cooldown() for the time.
export function cooldownUntilOf(error: unknown): string | null {
  if (!error || typeof error !== "object") return null;
  const details = (error as { details?: unknown }).details;
  if (typeof details !== "string") return null;
  const ms = Date.parse(details);
  return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

export function cooldownReply(error: unknown, nowMs: number): { status: number; body: Record<string, unknown> } {
  return {
    status: 429,
    body: {
      outcome: "quiz_cooldown",
      error: "Quiz cooldown",
      cooldown_until: cooldownUntilOf(error),
      server_now: new Date(nowMs).toISOString(),
    },
  };
}

// The privileged half of process-event: ownership of the answered instance, and the one RPC that
// runs with the backend key.
//
// WHY A SEPARATE CLIENT
// process_text_answer trusts its caller: it takes p_user_id and p_is_correct as parameters and
// awards XP, coins, streak and quest progress from them. Calling it with the pupil's own JWT means
// EXECUTE has to stay granted to `authenticated`, and then a pupil can call it directly through the
// public REST endpoint with p_is_correct = true. The fix is to make it backend-only (a separate D-110
// migration revokes EXECUTE from PUBLIC, anon and authenticated). This module is the backend side:
// the RPC goes through an admin client built from the shared resolver's backend key, and only from here.
//
// WHAT STAYS USER-SCOPED
// Everything else in process-event — auth.getUser(), reading the question instance (RLS), the MC /
// number RPC and the long-answer save — keeps the pupil's own client. Only this one call is
// privileged, so RLS still decides what the pupil can see.
//
// SAFETY RULES ENFORCED HERE
//   * The admin client never receives the pupil's Authorization header. If it did, PostgREST would
//     run the call as `authenticated`, which the lockdown denies — and before the lockdown it would
//     silently keep the hole open.
//   * p_user_id and p_is_correct come only from the caller's server-side values (the verified
//     user.id and the evaluator's boolean). Nothing is read from the request body here.
//   * If the admin client cannot be built — the resolver throws on a missing or broken key
//     configuration — the error propagates. There is deliberately no fallback to the user client.
//
// Pure TypeScript with no Deno or network imports, so the Node unit suite can import exactly what
// the Edge Function runs (same arrangement as _shared/answer-evaluation.ts).

export type RpcResult = { data: unknown; error: unknown };
export type RpcClient = { rpc: (fn: string, args: Record<string, unknown>) => PromiseLike<RpcResult> };

// Options for the admin client: a server-side, single-request client that never stores or refreshes
// a session. Global headers are intentionally absent — see "SAFETY RULES" above.
export const ADMIN_CLIENT_OPTIONS = Object.freeze({
  auth: Object.freeze({ persistSession: false, autoRefreshToken: false }),
});

// The answered instance must belong to the signed-in pupil. RLS already limits what the user client
// can read, but RLS also lets a teacher read their pupils' instances, and the admin client bypasses
// RLS entirely — so ownership is checked explicitly, before any answer path runs.
export function isInstanceOwner(instanceStudentId: unknown, userId: unknown): boolean {
  return typeof instanceStudentId === "string"
    && typeof userId === "string"
    && userId.length > 0
    && instanceStudentId === userId;
}

export type TextAnswerAward = {
  instanceId: string;
  userId: string;
  answer: string;
  isCorrect: boolean;
};

// Calls process_text_answer through a freshly built admin client. makeAdminClient is invoked only
// here, so the backend key is resolved only when the RPC is made; if it throws, so does this.
export async function callProcessTextAnswer(
  makeAdminClient: () => RpcClient,
  award: TextAnswerAward,
): Promise<RpcResult> {
  const admin = makeAdminClient();
  return await admin.rpc("process_text_answer", {
    p_instance_id: award.instanceId,
    p_user_id: award.userId,
    p_user_answer: award.answer,
    p_is_correct: award.isCorrect === true,
  });
}

// ── MC / number: process_question_attempt ────────────────────────────────────────────────────────
// Same model, second privileged RPC. process_question_attempt evaluates the answer itself against the
// instance's stored correct answer and awards XP/coins, streak and quests — or the reduced repeat
// award — exactly once per instance (its own answered = false guard). It trusts p_student_id, so it
// too is called only through the admin client, with the verified user.id, after the ownership check.
// Nothing about correctness, rewards or idempotency moves here: this only chooses the credential.

export type QuestionAttempt = {
  studentId: string;
  instanceId: string;
  answer: string;
  questionShownAt: number;
};

export async function callProcessQuestionAttempt(
  makeAdminClient: () => RpcClient,
  attempt: QuestionAttempt,
): Promise<RpcResult> {
  const admin = makeAdminClient();
  return await admin.rpc("process_question_attempt", {
    p_student_id: attempt.studentId,
    p_question_instance_id: attempt.instanceId,
    p_answer: attempt.answer,
    p_question_shown_at: attempt.questionShownAt,
  });
}

// ── H5: the _v2 functions (migration 20261030211428, D-273) ──────────────────────────────────────
// Same model again: both trust p_student_id / p_user_id (and p_is_correct), so they are called only
// through the admin client, with the verified user.id, after the ownership check. round_no and
// submission_id come from the validated request (./answer-v2.ts); review_text and misconception_type
// are what process-event shows for a wrong answer, so the database can freeze them in the attempt and
// write the misconception signal in the same transaction. The parameter names are the migration's.

// The names of the two legacy functions, for recognising their revoked EXECUTE after M2
// (./answer-v2.ts, isRevokedLegacyRpc). Kept here so this module stays the only one that names them.
export const LEGACY_ANSWER_RPCS = Object.freeze({ mc: "process_question_attempt", text: "process_text_answer" });

export type V2Submission ={ roundNo: number; submissionId: string; reviewText: string | null; misconceptionType: string | null };

// L1 K1 (migration 20261103110000, docs/learning-progression-l1-contracts.md §K1): the activity mode
// and the hints used are decided by the SERVER and are constants here until L3 (hints) and L5 (modes
// recorded on the instance). They are never read from the request body: a client that sends fields
// with these names is ignored, because nothing in this module takes them as arguments.
export const L1_ATTEMPT_CONTEXT = Object.freeze({ mode: "quiz_v1", hintsUsed: 0 });

// Lærligverse L5 + L3 (migration 20261108043500, ./attempt-context.ts): with LAERLIGVERSE_ATTEMPT_CONTEXT=on,
// process-event passes serverContext = true and the call goes to the WRAPPER (process_question_attempt_with_context /
// process_text_answer_with_context). The wrapper locks the round, derives mode (served_mode) and hints (the server's
// hint log) in the SAME transaction and calls the _v2 function above unchanged — so no p_mode or p_hints_used is
// sent at all. Off (the default): exactly the call above, with the L1 constants. Neither value ever comes from the
// request body.
export const ATTEMPT_CONTEXT_RPCS = Object.freeze({
  mc: "process_question_attempt_with_context",
  text: "process_text_answer_with_context",
});

export async function callProcessQuestionAttemptV2(
  makeAdminClient: () => RpcClient,
  attempt: Omit<QuestionAttempt, "questionShownAt"> & V2Submission,
  serverContext = false,
): Promise<RpcResult> {
  const admin = makeAdminClient();
  const args = {
    p_student_id: attempt.studentId,
    p_question_instance_id: attempt.instanceId,
    p_answer: attempt.answer,
    p_round_no: attempt.roundNo,
    p_submission_id: attempt.submissionId,
    p_review_text: attempt.reviewText,
    p_misconception_type: attempt.misconceptionType,
  };
  if (serverContext === true) return await admin.rpc(ATTEMPT_CONTEXT_RPCS.mc, args);
  return await admin.rpc("process_question_attempt_v2", {
    ...args,
    p_mode: L1_ATTEMPT_CONTEXT.mode,
    p_hints_used: L1_ATTEMPT_CONTEXT.hintsUsed,
  });
}

export async function callProcessTextAnswerV2(
  makeAdminClient: () => RpcClient,
  award: TextAnswerAward & V2Submission,
  serverContext = false,
): Promise<RpcResult> {
  const admin = makeAdminClient();
  const args = {
    p_instance_id: award.instanceId,
    p_user_id: award.userId,
    p_user_answer: award.answer,
    p_is_correct: award.isCorrect === true,
    p_round_no: award.roundNo,
    p_submission_id: award.submissionId,
    p_review_text: award.reviewText,
    p_misconception_type: award.misconceptionType,
  };
  if (serverContext === true) return await admin.rpc(ATTEMPT_CONTEXT_RPCS.text, args);
  return await admin.rpc("process_text_answer_v2", {
    ...args,
    p_mode: L1_ATTEMPT_CONTEXT.mode,
    p_hints_used: L1_ATTEMPT_CONTEXT.hintsUsed,
  });
}
